/**
 * Shared helpers for reading payment configuration off a Service entity.
 *
 * `payment.fixed` / `varied` / `custom` are a `@oneof` in the services SDK, so
 * only one is ever populated — reading `fixed` then `varied` covers both FIXED
 * and VARIED rate types.
 *
 * A percentage deposit stores no amount anywhere on the entity; the server
 * resolves it when the customer books. Hence the split between
 * {@link requiresDeposit} ("takes a deposit?") and {@link hasDeposit} ("has an
 * amount?") — a percentage deposit answers `true` and `false` respectively.
 *
 * @module Services/ServicePayment
 */
/**
 * Whether the service takes a deposit. An explicit `options.deposit` wins; when
 * the flag is absent a configured amount still counts, so a service that sets one
 * without the flag keeps reporting a deposit.
 */
export function requiresDeposit(service) {
    return service?.payment?.options?.deposit ?? hasDeposit(service);
}
/** The deposit amount, if one is configured as a fixed amount. */
export function getDepositValue(service) {
    const payment = service?.payment;
    return (payment?.fixed?.deposit?.value ??
        payment?.varied?.deposit?.value ??
        payment?.fixed?.depositDetails?.amount?.value ??
        payment?.varied?.depositDetails?.amount?.value);
}
export function hasDeposit(service) {
    const value = getDepositValue(service);
    return !!value && Number(value) > 0;
}
/** Meaningful only alongside `hasDeposit`. */
export function isFullUpfrontPaymentAllowed(service) {
    const payment = service?.payment;
    return !!(payment?.fixed?.fullUpfrontPaymentAllowed ??
        payment?.varied?.fullUpfrontPaymentAllowed);
}
